#include <iostream>
#include <string>
#include <algorithm>

int* analyzeDocument(const std::string& document) {
    bool inParentheses = false;
    bool lastWasLetter = false;
    int maxWordLength = 0;
    int currentWordLength = 0;
    int parenthesesWordCount = 0;

    for (size_t i = 0; i < document.length(); ++i) {
        char ch = document[i];
        if (ch == '(') {
            inParentheses = true;
            lastWasLetter = false;
            currentWordLength = 0;
        } else if (ch == ')') {
            inParentheses = false;
            lastWasLetter = false;
            currentWordLength = 0;
        } else if (std::isalpha(static_cast<unsigned char>(ch))) {
            if (inParentheses && !lastWasLetter) {
                parenthesesWordCount++;
            } else if (!inParentheses) {
                currentWordLength++;
                maxWordLength = std::max(maxWordLength, currentWordLength);
            }
            lastWasLetter = true;
        } else {
            lastWasLetter = false;
            currentWordLength = 0;
        }
    }
    int* result = new int[2];
    result[0] = maxWordLength;
    result[1] = parenthesesWordCount;
    return result;
}

int main() {
    int length;
    std::cin >> length;
    std::string document;
    std::cin >> document;
    int* result = analyzeDocument(document);
    std::cout << result[0] << " " << result[1] << std::endl;
    delete[] result;
    return 0;
}
